def remove_stones(stones):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        parent[find(a)] = find(b)

    for x, y in stones:
        union(x, ~y)

    roots = {find(x) for x, y in stones}
    return len(stones) - len(roots)

